import Foundation
#if canImport(Darwin)
import Darwin
#else
import Glibc
#endif

/// Byte guards for diagnostic/cache writers. Existing legacy files are never
/// rotated or deleted here. An oversized old log simply receives no new bytes.
enum BoundedDiskWriter {
    static let logCap:UInt64=10*1024*1024
    @discardableResult static func append(_ data:Data,to url:URL,cap:UInt64=logCap)->Bool {
        guard UInt64(data.count)<=cap else {return false}
        let fd=open(url.path,O_CREAT|O_WRONLY|O_APPEND|O_NOFOLLOW,mode_t(0o600));guard fd>=0 else {return false}
        defer {_ = flock(fd,LOCK_UN);close(fd)}
        guard flock(fd,LOCK_EX)==0 else {return false}
        var s=stat();guard fstat(fd,&s)==0,s.st_nlink==1,UInt64(max(0,s.st_size))+UInt64(data.count)<=cap else {return false}
        return data.withUnsafeBytes {raw in
            var at=0
            while at<raw.count {
                let n=write(fd,raw.baseAddress!.advanced(by:at),raw.count-at)
                if n<0 && errno==EINTR {continue};if n<=0 {return false};at+=n
            }
            return true
        }
    }
    /// New versioned subdirectory only; legacy siblings remain untouched. No
    /// pruning: full stores stop accepting diagnostic/cache copies. Successful
    /// callers still hold the original bytes in memory, so rendering is intact.
    @discardableResult static func save(_ data:Data,name:String,under parent:URL,cap:UInt64,entries:Int=256)->URL? {
        guard !name.isEmpty,name==URL(fileURLWithPath:name).lastPathComponent,!name.hasPrefix("."),UInt64(data.count)<=cap else {return nil}
        let fm=FileManager.default,root=parent.appendingPathComponent("bounded-v1",isDirectory:true)
        let existed=fm.fileExists(atPath:root.path)
        if !existed {
            do {try fm.createDirectory(at:root,withIntermediateDirectories:true);try Data("gor-bounded-v1".utf8).write(to:root.appendingPathComponent(".owner"),options:.withoutOverwriting)}catch {return nil}
        }
        guard DepthCacheBudget.plainDirectory(root),DepthCacheBudget.plainFile(root.appendingPathComponent(".owner")),(try? String(contentsOf:root.appendingPathComponent(".owner"),encoding:.utf8))=="gor-bounded-v1" else {return nil}
        return try? DepthCacheBudget.withLock(root) {
            let all=try fm.contentsOfDirectory(at:root,includingPropertiesForKeys:nil)
            let dest=root.appendingPathComponent(name)
            guard !fm.fileExists(atPath:dest.path),all.count<entries+2,try DepthCacheBudget.bytes(root)+UInt64(data.count)<=cap else {throw DepthCacheBudget.Failure.quota}
            let fd=open(dest.path,O_CREAT|O_EXCL|O_WRONLY|O_NOFOLLOW,mode_t(0o600));guard fd>=0 else {throw DepthCacheBudget.Failure.unsafe}
            // Keep the exclusive O_NOFOLLOW descriptor through the write. Reopening
            // its pathname would allow a rename/symlink race after validation.
            do {let h=FileHandle(fileDescriptor:fd,closeOnDealloc:false);defer {try? h.close()};try h.write(contentsOf:data)}catch {try? fm.removeItem(at:dest);throw error}
            return dest
        }
    }
}

Sources/gor/BoundedSubtitleDownload.swif:
import Foundation
#if canImport(FoundationNetworking)
import FoundationNetworking
#endif

/// Ephemeral, memory-only network reads. No URLSession download files or URL
/// cache are created. The delegate stops oversized bodies before keeping them.
final class BoundedSubtitleDownload: NSObject, URLSessionDataDelegate, @unchecked Sendable {
    static let subtitleLimit = 32 * 1024 * 1024
    private let limit: Int
    private var bytes = Data()
    private var completed = false
    private var session: URLSession?
    private let completion: (Data?) -> Void
    private init(limit: Int, completion: @escaping (Data?) -> Void) {
        self.limit = limit; self.completion = completion
    }
    static func fetch(_ request: URLRequest, limit: Int = subtitleLimit, completion: @escaping (Data?) -> Void) {
        guard limit > 0 else { completion(nil); return }
        let reader = BoundedSubtitleDownload(limit: limit, completion: completion)
        let config = URLSessionConfiguration.ephemeral
        config.urlCache = nil
        config.requestCachePolicy = .reloadIgnoringLocalCacheData
        config.timeoutIntervalForRequest = 30
        config.timeoutIntervalForResource = 60
        let queue = OperationQueue(); queue.maxConcurrentOperationCount = 1
        let session = URLSession(configuration: config, delegate: reader, delegateQueue: queue)
        reader.session = session
        session.dataTask(with: request).resume()
    }
    private func finish(_ data: Data?) {
        guard !completed else { return }; completed = true
        bytes.removeAll(keepingCapacity: false)
        completion(data)
        session?.invalidateAndCancel(); session = nil
    }
    func urlSession(_ session: URLSession, dataTask: URLSessionDataTask, didReceive response: URLResponse,
                    completionHandler: @escaping (URLSession.ResponseDisposition) -> Void) {
        guard let response = response as? HTTPURLResponse, (200..<300).contains(response.statusCode),
              response.expectedContentLength <= Int64(limit) else {
            completionHandler(.cancel); finish(nil); return
        }
        completionHandler(.allow)
    }
    func urlSession(_ session: URLSession, dataTask: URLSessionDataTask, didReceive data: Data) {
        guard !completed, data.count <= limit - bytes.count else { finish(nil); return }
        bytes.append(data)
    }
    func urlSession(_ session: URLSession, task: URLSessionTask, didCompleteWithError error: Error?) {
        guard !completed else { return }
        let result = error == nil && !bytes.isEmpty ? bytes : nil
        finish(result)
    }
}

Sources/gor/ComputeUnitsProbe.swift:
import Foundation
#if canImport(CoreML)
import CoreML

/// Which compute devices CoreML plans to use for a model (self-test log). Uses MLComputePlan (macOS 14.4+): per operation `deviceUsage(for:)`, summarised as op counts per
/// preferred device. This is the PLAN, not a runtime trace (the public API has no per-prediction device report); the log says "plan". UNVERIFIED on a Mac: the
/// MLComputePlan names below are from memory, so every failure path returns a readable string instead of throwing.
enum ComputeUnitsProbe {
    static func summary(of compiledOrPackage: URL, units: MLComputeUnits = .all) -> String {
        guard #available(macOS 14.4, *) else { return "unavailable (macOS < 14.4)" }
        let u = KitCompiledCache.loadable(compiledOrPackage)
        let cfg = MLModelConfiguration(); cfg.computeUnits = units
        var result = "unavailable (load did not finish)"
        let sem = DispatchSemaphore(value: 0)
        Task.detached {
            do {
                let plan = try await MLComputePlan.load(contentsOf: u, configuration: cfg)
                guard case .program(let program) = plan.modelStructure, let main = program.functions["main"] else { result = "unavailable (not an ML program)"; sem.signal(); return }
                var counts: [String: Int] = [:]
                for op in main.block.operations {
                    let name: String
                    switch plan.deviceUsage(for: op)?.preferred {
                    case .some(let d) where d is MLNeuralEngineComputeDevice: name = "ane"
                    case .some(let d) where d is MLGPUComputeDevice: name = "gpu"
                    case .some(let d) where d is MLCPUComputeDevice: name = "cpu"
                    default: name = "none"
                    }
                    counts[name, default: 0] += 1
                }
                result = "plan ops " + counts.sorted { $0.key < $1.key }.map { "\($0.key)=\($0.value)" }.joined(separator: " ")
            } catch { result = "unavailable (\(error))" }
            sem.signal()
        }
        _ = sem.wait(timeout: .now() + 60)
        return result
    }
}
#endif

