    /// cuts.py shots_from_cuts: bounds = [0] + cuts(0 < c < n) + [n]; shot i = (bounds[i], bounds[i+1] - 1) inclusive.
    static func shots(nFrames: Int, cuts: [Int]) -> [[Int]] {
