    static func detect(next: () -> [UInt8]?, threshold: Double = ShotCuts.threshold) -> (cuts: [Int], nFrames: Int) {
        var s = SceneScorer(), cuts: [Int] = [], n = 0
        while let f = next() { let r = s.score(luma: f); if n > 0, r.score >= threshold { cuts.append(n) }; n += 1 }
