            float3 a = isL ? left.read(uint2(2u * x, gid.y)).rgb : right.read(uint2(2u * x, gid.y)).rgb;
            float3 b = isL ? left.read(uint2(2u * x + 1u, gid.y)).rgb : right.read(uint2(2u * x + 1u, gid.y)).rgb;
            outTex.write(float4((a + b) * 0.5f, 1.0f), gid);
