    }
    static func internalMedia(_ path:String)->Bool {
        path.hasPrefix(DepthCachePaths.root.path+"/") && URL(fileURLWithPath:path).lastPathComponent.range(of:#"^(?:render|source)_shot_[0-9]+\.mp4$"#,options:.regularExpression) != nil
    }
