    /// tools/depth_analysis/depth_guards.py texture_weights).
    static func textureWeights(luma: [Float], w: Int, h: Int, lo: Float = 1.0, hi: Float = 8.0) -> [Float] {
        let tex = localStd(luma, w: w, h: h)
