            for (int k = 0; k < 4; k++) s[k] += work.read(uint2((uint)clamp(x + 1 + R[k], 0, n - 1), gid)).rgb - work.read(uint2((uint)clamp(x - R[k], 0, n - 1), gid)).rgb;
