        case 8: Stereo3DExperiments.toggleDepthOfField();onExperimentChange();receipt("row-\(row.tag)");return
        case 9: Stereo3DExperiments.toggleHoleFillGradient();onExperimentChange();receipt("row-\(row.tag)");return
